// AKN-PT Editor — smoke tests (run from project root with Node)
// Validates that the XML generated by the editor passes XSD + Schematron.
//
// Usage:
//   node editor/smoke-test.js
//   python -m akn_pt batch editor/.smoke-output
//
// EUPL-1.2
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname);
const OUT = path.join(ROOT, '.smoke-output');
fs.mkdirSync(OUT, { recursive: true });

function loadFile(rel) {
  const code = fs.readFileSync(path.join(ROOT, rel), 'utf8');
  eval(`(function() { ${code};
    if (typeof newDocument !== 'undefined') global.newDocument = newDocument;
    if (typeof ACT_TYPES !== 'undefined') global.ACT_TYPES = ACT_TYPES;
    if (typeof FORMULAS !== 'undefined') global.FORMULAS = FORMULAS;
    if (typeof AknExport !== 'undefined') global.AknExport = AknExport;
    if (typeof ImportParser !== 'undefined') global.ImportParser = ImportParser;
    if (typeof References !== 'undefined') { global.References = References; globalThis.References = References; }
    if (typeof Amendment !== 'undefined') { global.Amendment = Amendment; globalThis.Amendment = Amendment; }
    if (typeof Preview !== 'undefined') { global.Preview = Preview; globalThis.Preview = Preview; }
    if (typeof Diff !== 'undefined') { global.Diff = Diff; globalThis.Diff = Diff; }
    if (typeof LodaInline !== 'undefined') { global.LodaInline = LodaInline; globalThis.LodaInline = LodaInline; }
    if (typeof BluebellPt !== 'undefined') { global.BluebellPt = BluebellPt; globalThis.BluebellPt = BluebellPt; }
    if (typeof DreMock !== 'undefined') { global.DreMock = DreMock; globalThis.DreMock = DreMock; }
    // expor para todos os módulos (akn-export precisa de ler References no fecho global)
    if (typeof AknExport !== 'undefined') globalThis.AknExport = AknExport;
  })();`);
}
loadFile('js/templates.js');
loadFile('js/references.js');  // tem de carregar antes do akn-export para o xmlText resolver
loadFile('js/dre-mock.js');
loadFile('js/akn-export.js');
loadFile('js/preview.js');
loadFile('js/diff.js');
loadFile('js/amendment.js');
loadFile('js/loda-inline.js');
loadFile('js/bluebell-pt.js');
loadFile('js/import-parser.js');

// State precisa de localStorage (shim) e ignora Editor.refresh (guard typeof).
const _mem = {};
global.localStorage = {
  getItem: (k) => _mem[k] || null,
  setItem: (k, v) => { _mem[k] = String(v); },
  removeItem: (k) => { delete _mem[k]; },
};
loadFile('js/state.js');
// expor State (definido via IIFE em state.js)
eval(fs.readFileSync(path.join(ROOT, 'js/state.js'), 'utf8') + '\nglobal.State = State;');

