let n_ok = 0, n_fail = 0;
console.log(`Generating ${cases.length} test files (templates) + 1 imported in ${OUT}/\n`);

// 1. Tests from rich templates with user overrides
for (const c of cases) {
  try {
    const doc = global.newDocument(c.type);
    c.setup(doc);
    const xml = global.AknExport.toXml(doc);
    const file = path.join(OUT, `${c.name}.akn.xml`);
    fs.writeFileSync(file, xml);
    console.log(`  OK   ${c.name}.akn.xml  (${xml.length} bytes)`);
    n_ok++;
  } catch (e) {
    console.log(`  FAIL ${c.name}: ${e.message}`);
    n_fail++;
  }
}

